// Piezas con "lista": true que aún no se han ofrecido esta semana (se recuerdan entre ejecuciones)
const memoria = $getWorkflowStaticData('global');
memoria.ofrecidas = memoria.ofrecidas || {};
const salida = [];
for (const pieza of Object.values($input.first().json.piezas || {})) {
  const clave = `${pieza.tipo}-${pieza.semana}`;
  if (!pieza.lista || memoria.ofrecidas[clave]) continue;
  memoria.ofrecidas[clave] = new Date().toISOString();
  salida.push({ json: { pieza } });
}
// Olvidar lo de hace más de 2 meses
for (const [clave, cuando] of Object.entries(memoria.ofrecidas)) {
  if (Date.now() - new Date(cuando) > 60 * 864e5) delete memoria.ofrecidas[clave];
}
return salida;

// Avisos de cambios de partido que aún no se han mandado
const memoria = $getWorkflowStaticData('global');
const avisos = $input.first().json.avisos || [];
if (!memoria.avisosVistos) {
  // Primera vez: se dan por vistos los que ya había, para no mandar avisos viejos de golpe
  memoria.avisosVistos = avisos.map(a => a.id);
  return [];
}
const nuevos = avisos.filter(a => !memoria.avisosVistos.includes(a.id));
memoria.avisosVistos = [...memoria.avisosVistos, ...nuevos.map(a => a.id)].slice(-300);
return nuevos.map(a => ({ json: { texto: a.texto } }));

// Foto del post + petición del texto. Sirve para las piezas programadas y para /publicar
return $input.all().map(item => {
  const p = item.json.pieza;
  const falta = (p.faltan || []).length ? `\n⚠️ Ojo, falta: ${p.faltan.join('; ')}` : '';
  return { json: { pieza: p, foto: p.post,
    texto: `${p.nombre} lista para publicar ✅${falta}\n\n✍️ RESPONDE A ESTE MENSAJE (mantén pulsado → Responder) con el texto de la publicación.` } };
});

// Se apunta qué pieza corresponde a cada foto, para reconocer la respuesta
const memoria = $getWorkflowStaticData('global');
memoria.pendientes = memoria.pendientes || {};
const piezas = $('Preparar pregunta').all();
$input.all().forEach((item, i) => { memoria.pendientes[item.json.message_id] = piezas[i].json.pieza; });
// Solo se guardan las 30 últimas
const ids = Object.keys(memoria.pendientes);
ids.slice(0, Math.max(0, ids.length - 30)).forEach(id => delete memoria.pendientes[id]);
return [];

// Decide qué hacer con cada mensaje o botón del grupo. Sin IA: reglas fijas.
const upd = $('Telegram (grupo)').first().json;
const piezas = $input.first().json.piezas || {};
const memoria = $getWorkflowStaticData('global');
memoria.pendientes = memoria.pendientes || {};
memoria.borradores = memoria.borradores || {};
const salir = (...cosas) => cosas.map(json => ({ json }));
const mensaje = texto => ({ accion: 'mensaje', texto });

// ---------- botones
const cb = upd.callback_query;
if (cb) {
  const [accion, clave] = String(cb.data || '').split(':');
  const b = memoria.borradores[clave];
  if (!b) return salir(mensaje('Ese botón ya no vale (es de una publicación anterior).'));
  const p = b.pieza;
  if (accion === 'pub') {
    // 🧪 ENSAYO: aquí irá la publicación real en Instagram (post con este texto)
    return salir(
      mensaje(`✅ (ensayo) Se habría publicado el post de ${p.nombre} con este texto:\n\n${b.texto}`),
      { accion: 'botones', foto: p.historia, texto: `¿Subo también la historia de ${p.nombre}?`,
        boton1: '✅ Subir historia', dato1: `his:${clave}`, boton2: 'No', dato2: `nohis:${clave}` });
  }
  if (accion === 'can') return salir(mensaje(`❌ Cancelado. Para poner otro texto, responde otra vez a la foto de ${p.nombre}.`));
  if (accion === 'his') {
    delete memoria.borradores[clave];
    // 🧪 ENSAYO: aquí irá la historia real en Instagram
    return salir(mensaje(`✅ (ensayo) Se habría subido la historia de ${p.nombre}.`));
  }
  if (accion === 'nohis') { delete memoria.borradores[clave]; return salir(mensaje('Vale, sin historia.')); }
  return [];
}

// ---------- mensajes
const msg = upd.message;
if (!msg || !msg.text) return [];
const texto = msg.text.trim();

// Respuesta a una foto que pedía texto → es el texto de la publicación
const respondida = msg.reply_to_message && memoria.pendientes[msg.reply_to_message.message_id];
if (respondida) {
  const p = respondida;
  const clave = `${p.tipo}-${p.semana}-${Date.now().toString(36)}`;
  memoria.borradores[clave] = { pieza: p, texto };
  const ids = Object.keys(memoria.borradores);
  ids.slice(0, Math.max(0, ids.length - 30)).forEach(id => delete memoria.borradores[id]);
  // El pie de una foto en Telegram admite unos 1000 caracteres: si es más largo, se enseña aparte
  const largo = texto.length > 850;
  return salir(
    ...(largo ? [mensaje(texto)] : []),
    { accion: 'botones', foto: p.post,
      texto: `${largo ? '(texto arriba)' : texto}\n\n— ¿Publico ${p.nombre} con este texto?`,
      boton1: '✅ Publicar', dato1: `pub:${clave}`, boton2: '❌ Cancelar', dato2: `can:${clave}` });
}

// Respuesta a una foto del bot que no está en la memoria (p. ej. mandada en una prueba manual)
const citada = msg.reply_to_message;
if (citada && citada.from && citada.from.is_bot && citada.photo) {
  return salir(mensaje('🤔 No tengo apuntada esa foto (puede ser de una prueba o muy antigua). Escribe /publicar y la pieza (por ejemplo /publicar matchday) y responde a la foto nueva.'));
}

// Comandos
if (!texto.startsWith('/')) return [];
const [orden, arg] = texto.split(/\s+/);
const comando = orden.split('@')[0].toLowerCase();
const estado = p => p.lista ? 'lista ✅' : `no lista ⏳ (falta: ${(p.faltan || []).join('; ')})`;
const verPieza = p => ({ accion: 'foto', foto: p.post, texto: `${p.nombre}: ${estado(p)}` });
const lista = Object.values(piezas);

if (comando === '/estado') {
  if (!lista.length) return salir(mensaje('Esta semana no hay ninguna publicación con datos.'));
  return salir(mensaje('📋 Publicaciones de esta semana:\n' + lista.map(p => `• ${p.nombre}: ${estado(p)}`).join('\n')));
}
if (['/ordutegia', '/emaitzak', '/matchday'].includes(comando)) {
  const tipo = comando.slice(1);
  const elegidas = lista.filter(p => p.tipo === tipo || (tipo === 'matchday' && p.tipo.startsWith('matchday')));
  return elegidas.length ? salir(...elegidas.map(verPieza)) : salir(mensaje(`Esta semana no hay ${tipo.toUpperCase()}.`));
}
if (comando === '/publicar') {
  const p = piezas[(arg || '').toLowerCase()];
  if (!p) return salir(mensaje(`¿Cuál? Escribe /publicar y una de estas: ${Object.keys(piezas).join(', ') || '(ninguna esta semana)'}`));
  return salir({ accion: 'preguntar', pieza: p });
}
if (comando === '/ayuda' || comando === '/start') {
  return salir(mensaje('🤖 Comandos:\n/estado → qué publicaciones están listas y qué falta\n/ordutegia, /emaitzak, /matchday → ver la imagen\n/publicar <pieza> → publicar una pieza aunque no esté lista (p. ej. /publicar emaitzak)\n\nPara poner el texto de una publicación, responde a la foto que manda el bot.'));
}
return [];
